// Chalchiuhtlicue (or Mesoamerican design) 🌽 #WCCChallenge
//
// Play with Truchet tiles this week. (*•̀ㅂ•́)و
//
// The color tab can edit the color for most units. :)
// I don't want to color it today, maybe tomorrow. :p
//
// Canvas size:
//     width:  COLS * CELL_SIZE * PIXEL_DENSITY
//     height: ROWS * CELL_SIZE * PIXEL_DENSITY

const [COLS, ROWS] = [10, 5]
const CELL_SIZE = 60
const PIXEL_DENSITY = 4

const [WIDTH, HEIGHT] = [COLS * CELL_SIZE, ROWS * CELL_SIZE]
const SQRT2 = 1.41421356237
const STROKE_WEIGHT = CELL_SIZE / 60
const MAIN_AREA_SCALE = 1.5
const arcSM = (CELL_SIZE / 3) * (3 - MAIN_AREA_SCALE)
const arcLG = (CELL_SIZE / 3) * (3 + MAIN_AREA_SCALE)
const grid = Array.from({ length: ROWS }, () => Array(COLS))

function setup() {
	createCanvas(WIDTH, HEIGHT)
	flex({ container: { width: "95%", height: "95%" } })
	pixelDensity(PIXEL_DENSITY)
	angleMode(DEGREES)

	setPalette(random(palettes))
	stroke(STROKE_COLOR)
	strokeWeight(STROKE_WEIGHT)
	background(BG_COLOR)

	for (let y = 0; y < ROWS; y++) {
		for (let x = 0; x < COLS; x++) {
			grid[y][x] = random([Truchet, Dino, Human, Skull])
			if (x >= 1 && grid[y][x - 1] === Skull)
				grid[y][x] = random([Truchet, Dino, Human])
			if (y >= 1 && grid[y - 1][x] === Skull)
				grid[y][x] = random([Truchet, Dino, Human])

			let angle = random([0, 90, 180, 270])
			const posX = x * (WIDTH / COLS)
			const posY = y * (HEIGHT / ROWS)
			grid[y][x](posX, posY, angle)
		}
	}
}


// === Tab: Human ===
const Human = (x, y, angle) => {
	// Background
	layer({ x, y, angle }, () => {
		noStroke()
		fill(BG_COLOR)
		square(0, 0, 1)
	})

	// Top of Head
	layer({ x, y, angle }, () => {
		fill(HUMAN_COLOR)
		let h = (arcLG - arcSM) / 3
		arc(CELL_SIZE / 2, 0, (arcLG - arcSM) / 2, h, 0, 180)
		if (random() < 0.5) paw()
	})

	// Right Face
	layer({ x, y, angle: angle + 180 }, () => {
		fill(HUMAN_COLOR)
		arc(0, 0, arcLG, arcLG, 0, 90)
		fill(BG_COLOR)
		arc(0, 0, arcSM, arcSM, 0, 90)
	})

	// Left Face
	layer({ x, y, angle: angle + 270 }, () => {
		fill(HUMAN_COLOR)
		arc(0, 0, arcLG, arcLG, 0, 90)
		fill(BG_COLOR)
		arc(0, 0, arcSM, arcSM, 0, 90)
	})

	// Right Face (show outline)
	layer({ x, y, angle: angle + 180 }, () => {
		noFill()
		arc(0, 0, arcLG, arcLG, 0, 90)
		arc(0, 0, arcSM, arcSM, 0, 90)
	})

	// 人中 :p
	layer({ x, y, angle }, () => {
		fill(STROKE_COLOR)
		strokeWeight(STROKE_WEIGHT * 0.1)
		shape(data.tattoo, 0.5, 0.7, 0.2, 0)
	})

	// Tattoo
	layer({ x, y, angle }, () => {
		fill(HUMAN_TATTOO_COLOR)
		strokeWeight(STROKE_WEIGHT)

		for (let i = 0; i < 2; i++) {
			const dir = -(i * 2 - 1)
			// under eyes
			shape(data.tattoo, abs(0.25 - i), 0.35, 1, 0 * dir)
			shape(data.tattoo, abs(0.175 - i), 0.5, 0.5, 90 * dir)
			shape(data.tattoo, abs(0.175 - i), 0.425, 0.5, 90 * dir)
			// under face
			shape(data.tattoo, abs(0.2 - i), 0.8, 0.4, -150 * dir)
			shape(data.tattoo, abs(0.15 - i), 0.75, 0.4, -150 * dir)
			shape(data.tattoo, abs(0.1 - i), 0.7, 0.4, -150 * dir)
		}
	})

	// Eyes
	layer({ x, y, angle }, () => {
		fill(HUMAN_EYE_COLOR)
		shape(data.eye, 0.25, 0.3, 0.3, 180)
		shape(data.eye, 0.75, 0.3, 0.3, 180)
		fill(HUMAN_IRIS_COLOR)
		Circle(0.25, 0.3, 0.1)
		Circle(0.75, 0.3, 0.1)
		fill(HUMAN_NOSE_COLOR)
		shape(data.nose, 0.5, 0.5, 0.5, 0)
	})

	// Mouth
	layer({ x, y, angle }, () => {
		fill(HUMAN_MOUTH_COLOR)
		strokeWeight(STROKE_WEIGHT * 0.5)
		shape(data.mouthFill, 0.5, 0.8, 0.3, 0)
		strokeWeight(STROKE_WEIGHT)
		outline(data.mouth, 0.5, 0.8, 0.3, 0)
		noFill()
		Arc(0.5, 0.93, 0.1, 0.03, 210, 330)
	})

	// Decoration
	fstDecorate(x, y, angle)
	secDecorate(x, y, angle)
}


// === Tab: Dino ===
const Dino = (x, y, angle) => {
	Truchet(x, y, angle)
	const flipX = random([true, false])

	// Tooth
	layer({ x, y, angle, flipX }, () => {
		strokeWeight(STROKE_WEIGHT * 0.6)
		fill(DINO_TOOTH_COLOR)
		for (let i = 0; i < 4; i++) {
			shape(data.tooth, 0.15 + i * 0.05, 0.5, 0.25, 0)
			shape(data.tooth, 0.15 + i * 0.05, 0.67, 0.25, 180)
		}
	})

	// Body
	layer({ x, y, angle, flipX }, () => {
		fill(DINO_COLOR)
		shape(data.dino, 0.5, 0.5, 1, 0, false)
	})

	// Eye
	layer({ x, y, angle, flipX }, () => {
		fill(DINO_EYE_COLOR)
		Circle(0.53, 0.4, 0.25)
	})

	// Nose
	layer({ x, y, angle, flipX }, () => {
		strokeWeight(STROKE_WEIGHT * 0.7)
		fill(DINO_NOSE_COLOR)
		shape(data.tooth, 0.2, 0.35, 0.3, 180)
	})

	// Scar
	layer({ x, y, angle, flipX }, () => {
		fill(DINO_SCAR_COLOR)
		shape(data.scar, 0.53, 0.75, 0.5, 0)
	})

	// Tattoo
	layer({ x, y, angle, flipX }, () => {
		noStroke()
		fill(DINO_TATTOO_COLOR)
		// Order: eye, right body, left body
		for (let i = 0; i < 3; i++)
			shape(data.tattoo, 0.6 + i * 0.025, 0.55 - i * 0.025, 0.2, -30 * (i + 1))
		for (let i = 0; i < 5; i++)
			shape(data.tattoo, 0.625, 0.65 + i * 0.05, 0.25, -90)
		for (let i = 0; i < 3; i++)
			shape(data.tattoo, 0.4, 0.75 + 0.05 * i, 0.25, 90)
	})
}


// === Tab: Skull ===
const drawSkull = (x, y, angle) => {
	// Body
	layer({ x, y, angle }, () => {
		fill(SKULL_COLOR)
		shape(data.skull, 0.5, 0, 1, 0, false)
	})

	// Eye
	layer({ x, y, angle }, () => {
		if (random() < 0.75) fill(SKULL_EYE_COLOR)
		else fill(BG_COLOR)
		shape(data.skullEye, 0.39, 0.07, 0.35, 0)
	})
	layer({ x, y, angle, flipX: true }, () => {
		if (random() < 0.75) fill(SKULL_EYE_COLOR)
		else fill(BG_COLOR)
		shape(data.skullEye, 0.39, 0.07, 0.35, 0)
	})

	// Nose
	layer({ x, y, angle }, () => {
		strokeWeight(STROKE_WEIGHT * 0.75)
		shape(data.tattoo, 0.49, 0.15, 0.15, 180)
		shape(data.tattoo, 0.51, 0.15, 0.15, 180)
	})
}

const paw = () => {
	shape(data.tooth, 0.69, 0.09, 0.5, -35)
	shape(data.tooth, 0.6, 0.14, 0.5, -20)
	shape(data.tooth, 0.5, 0.15, 0.5, 0)
	shape(data.tooth, 0.4, 0.14, 0.5, 20)
	shape(data.tooth, 0.31, 0.09, 0.5, 35)
}

const end = (x, y, angle) => {
	layer({ x, y, angle }, () => {
		var h = (arcLG - arcSM) / 3
		fill(FG_COLOR)
		arc(CELL_SIZE / 2, 0, (arcLG - arcSM) / 2, h, 0, 180)
		if (random() < 0.8) paw()
	})
}

const cross = (x, y, angle) => {
	layer({ x, y, angle: angle + 45 }, () => {
		fill(SKULL_CROSS_COLOR)
		Ellipse(0.5, 0.5, 0.5, 0.1)
		Ellipse(0.5, 0.5, 0.1, 0.5)
	})
}

const tube = (x, y, angle) => {
	layer({ x, y, angle }, () => {
		strokeCap(SQUARE)
		fill(SKULL_TUBE_COLOR)
		Arc(0, 0, 1.15, 1.15, 5, 85)
		fill(BG_COLOR)
		Arc(0, 0, 0.85, 0.85, 2, 88)
	})

	layer({ x, y, angle: angle + 180 }, () => {
		strokeCap(SQUARE)
		fill(SKULL_TUBE_COLOR)
		Arc(0, 0, 1.15, 1.15, 5, 85)
		fill(BG_COLOR)
		Arc(0, 0, 0.85, 0.85, 2, 88)
	})
}

const radiance = (x, y, angle) => {
	layer({ x, y, angle }, () => {
		fill(STROKE_COLOR)
		strokeWeight(STROKE_WEIGHT)
		shape(data.tattoo, 0.425, 0.575, 0.5, 45)
		shape(data.tattoo, 0.575, 0.575, 0.5, -45)
		shape(data.tattoo, 0.425, 0.425, 0.5, 135)
		shape(data.tattoo, 0.575, 0.425, 0.5, -135)
	})
}

const cube = (x, y, angle) => {
	layer({ x, y, angle: 45 }, () => {
		rectMode(CENTER)
		fill(SKULL_CUBE_COLOR)
		Square(0.5, 0.5, 0.12, 0.015)
	})
	if (random() < 0.5) radiance(x, y, 0)
}

const Skull = (x, y, angle) => {
	cube(x, y, angle)

	random([cross, tube])(x, y, angle)
	if (random() < 0.5) tube(x, y, angle + 90)

	random([drawSkull, end])(x, y, 0)
	random([drawSkull, end])(x, y, 90)
	random([drawSkull, end])(x, y, 180)
	random([drawSkull, end])(x, y, 270)

	fstDecorate(x, y, angle)
	secDecorate(x, y, angle)
}


// === Tab: Truchet ===
const crest = (arcLG) => {
	const r = arcLG / 2
	const al = (r * TAU) / 4
	const amount = 5
	const firstPoint = alrToAngle(al / (amount * 2), r)
	let d = dist(r, 0, cos(firstPoint) * r, sin(firstPoint) * r)
	d -= STROKE_WEIGHT / 2

	const type = random(["short", "mix"])
	const mouthRange = 97
	for (let i = 0; i < amount; i++) {
		push()
		const t = alrToAngle((al / (amount * 2)) * (i * 2 + 1), r)
		translate(cos(t) * r * 0.9, sin(t) * r * 0.9)
		rotate(t)

		switch (type) {
			case "short":
				fill(TRUCHET_CREST_SHORT_COLOR)
				strokeCap(SQUARE)
				arc(0, 0, d / 4, d, -mouthRange, mouthRange)
				strokeCap(ROUND)
				arc(0, 0, r * 0.45, d, mouthRange - 5, -(mouthRange - 5))
				break
			case "mix":
				fill(i % 2 === 0 ? TRUCHET_CREST_SHORT_COLOR : TRUCHET_CREST_LONG_COLOR)
				strokeCap(SQUARE)
				arc(0, 0, d / 4, d, -mouthRange, mouthRange)
				strokeCap(ROUND)
				if (i % 2 === 0) arc(0, 0, r * 0.45, d, mouthRange, -mouthRange)
				else arc(0, 0, r * 0.9, d, mouthRange, -mouthRange)
				break
		}
		pop()
	}

	if (type === "short") {
		push()
		noFill()
		const shift = 12.5
		const st = 0 + shift
		const ed = 90 - shift
		arc(0, 0, arcLG * 0.45, arcLG * 0.45, st, ed)
		arc(0, 0, arcLG * 0.55, arcLG * 0.55, st, ed)
		circle(
			cos(st) * arcLG * 0.25,
			sin(st) * arcLG * 0.25,
			arcLG * 0.5 - arcLG * 0.45
		)
		circle(
			cos(ed) * arcLG * 0.25,
			sin(ed) * arcLG * 0.25,
			arcLG * 0.5 - arcLG * 0.45
		)
		stroke(TRUCHET_ARC_COLOR)
		strokeWeight(arcLG * 0.5 - arcLG * 0.45 - STROKE_WEIGHT * 0.975)
		arc(0, 0, arcLG * 0.5, arcLG * 0.5, st, ed)
		pop()
	}
}

const backFeathers = (arcLG) => {
	push()
	fill(BG_COLOR)
	var r = arcLG / 2
	var al = (r * TAU) / 4
	var amount = 4
	var firstPoint = alrToAngle(al / (amount * 2), r)
	var d = dist(r, 0, cos(firstPoint) * r, sin(firstPoint) * r)
	d -= STROKE_WEIGHT / 2
	for (let i = 0; i < amount; i++) {
		push()
		var t = alrToAngle((al / (amount * 2)) * (i * 2 + 1), r)
		translate(cos(t) * r, sin(t) * r)
		rotate(t)
		var mouthRange = 97
		fill(TRUCHET_FEATHER_COLOR)
		arc(0, 0, d * 3, d * 2, -mouthRange, mouthRange)
		fill(TRUCHET_FEATHER_DOT_COLOR)
		circle(d / 1.5, 0, d / 1.5)
		pop()
	}
	pop()
}

const zigzag = (posX, posY, angle) => {
	push()
	const rot = random([90, 270])
	const trans = (CELL_SIZE / 2 / SQRT2) * (rot === 90 ? 0.98 : 0.93)
	translate(trans, trans)
	rotate(rot)
	fill(TRUCHET_ZIGZAG_COLOR)
	shape(data.zigzag, 0, 0, 0.65, 0)
	fill(TRUCHET_ZIGZAG_DOTS_COLOR)
	Circle(-0.086667, 0.086667, 0.108334)
	Circle(-0.086667, -0.216667, 0.108334)
	Circle(0.216667, 0.086667, 0.108334)
	pop()
}

const drawTruchet = (x, y, angle, order) => {
	if (order === "first") fstDecorate(x, y, angle)

	layer({ x, y, angle }, () => {
		const mainArea = (arcLG - arcSM) / 2
		if (random() < 0.5) backFeathers(arcLG)
		fill(TRUCHET_COLOR)
		arc(0, 0, arcLG, arcLG, 0, 90)
		fill(BG_COLOR)
		arc(0, 0, arcSM, arcSM, 0, 90)
		if (random() < 0.5) zigzag(x, y, angle)
		else crest(arcLG)
	})

	if (order === "second") secDecorate(x, y, angle)
}

const Truchet = (posX, posY, angle) => {
	drawTruchet(posX, posY, angle, "first")
	drawTruchet(posX, posY, angle + 180, "second")
}


// === Tab: Decoration ===
const threeDots = (x, y, angle, size) => {
	const sm = CELL_SIZE * (0.5 / 3)
	const lg = CELL_SIZE * (1 / 3)
	const md = sm + (lg - sm) * 0.5

	var r = md / 2
	var al = (r * TAU) / 4
	var amount = 3
	var firstPoint = alrToAngle(al / (amount * 2), r)
	var d = dist(r, 0, cos(firstPoint) * r, sin(firstPoint) * r)
	d -= STROKE_WEIGHT / 2

	layer({ x, y, angle: angle + 90 }, () => {
		for (let i = 0; i < amount; i++) {
			push()
			var t = alrToAngle((al / (amount * 2)) * (i * 2 + 1), r)
			translate(cos(t) * r, sin(t) * r)
			rotate(t)
			fill(DECORATION_DOT_COLOR)
			Circle(0, 0, size)
			pop()
		}
	})

	layer({ x, y, angle: angle + 270 }, () => {
		for (let i = 0; i < amount; i++) {
			push()
			var t = alrToAngle((al / (amount * 2)) * (i * 2 + 1), r)
			translate(cos(t) * r, sin(t) * r)
			rotate(t)
			fill(DECORATION_DOT_COLOR)
			Circle(0, 0, size)
			pop()
		}
	})
}

const threeBalls = (x, y, angle, size) => {
	var sm = CELL_SIZE * (0.5 / 3)
	var lg = CELL_SIZE * (1 / 3)
	var md = sm + (lg - sm) * 0.5

	var r = md / 2
	var al = (r * TAU) / 4
	var amount = 3
	var firstPoint = alrToAngle(al / 3, r)
	var d = dist(r, 0, cos(firstPoint) * r, sin(firstPoint) * r)
	d += STROKE_WEIGHT

	fill(DECORATION_COLOR)

	layer({ x, y, angle: angle + 90 }, () => {
		for (let i = 0; i < amount; i++) {
			push()
			var t = alrToAngle((al / (amount - 1)) * i, r)
			translate(cos(t) * r, sin(t) * r)
			rotate(t)
			if (i === 0) arc(0, 0, d, d, 0, 180)
			if (i === 1) arc(0, 0, d, d, 0, 360)
			if (i === 2) arc(0, 0, d, d, 180, 0)
			pop()
		}
	})

	layer({ x, y, angle: angle + 270 }, () => {
		for (let i = 0; i < amount; i++) {
			push()
			var t = alrToAngle((al / (amount - 1)) * i, r)
			translate(cos(t) * r, sin(t) * r)
			rotate(t)
			if (i === 0) arc(0, 0, d, d, 0, 180)
			if (i === 1) arc(0, 0, d, d, 0, 360)
			if (i === 2) arc(0, 0, d, d, 180, 0)
			pop()
		}
	})
}

const cornerRing = (x, y, angle, type) => {
	layer({ x, y, angle }, () => {
		var sm = 0.5 / 3
		var lg = 1 / 3
		if (type === "first") {
			fill(DECORATION_COLOR)
			Arc(1, 0, lg, lg, 90, 180)
			Arc(0, 1, lg, lg, 270, 360)
			fill(BG_COLOR)
			Arc(1, 0, sm, sm, 90, 180)
			Arc(0, 1, sm, sm, 270, 360)
		}
		if (type === "second") {
			fill(DECORATION_COLOR)
			Arc(0, 0, lg, lg, 0, 90)
			Arc(1, 1, lg, lg, 180, 270)
			fill(BG_COLOR)
			Arc(0, 0, sm, sm, 0, 90)
			Arc(1, 1, sm, sm, 180, 270)
		}
	})
}

const fstDecorate = (x, y, angle) => {
	if (random() < 0.5) {
		cornerRing(x, y, angle, "first")
		if (random() < 0.5) threeDots(x, y, angle, 0.025)
	} else threeBalls(x, y, angle, 0.025)
}

const secDecorate = (x, y, angle) => {
	if (random() < 0.5) {
		cornerRing(x, y, angle, "second")
		if (random() < 0.5) threeDots(x, y, angle + 90, 0.025)
	} else threeBalls(x, y, angle + 90, 0.025)
}


// === Tab: tools ===
const Ellipse = (x, y, w, h) =>
	ellipse(x * CELL_SIZE, y * CELL_SIZE, w * CELL_SIZE, h * CELL_SIZE)

const Square = (x, y, s, t) =>
	square(x * CELL_SIZE, y * CELL_SIZE, s * CELL_SIZE, t * CELL_SIZE)

const Circle = (x, y, d) => circle(x * CELL_SIZE, y * CELL_SIZE, d * CELL_SIZE)

const Arc = (x, y, w, h, start, stop) =>
	arc(x * CELL_SIZE, y * CELL_SIZE, w * CELL_SIZE, h * CELL_SIZE, start, stop)

const alrToAngle = (arcLength, radius) => (arcLength / radius) * (180 / PI)

const shape = (nodes, posX, posY, size, angle, CLOSE = true) => {
	push()
	posX *= CELL_SIZE
	posY *= CELL_SIZE
	size *= CELL_SIZE
	translate(posX, posY)
	rotate(angle)
	beginShape()
	nodes.forEach(({ x, y }) => curveVertex(x * size, y * size))
	if (CLOSE) {
		curveVertex(nodes[0].x * size, nodes[0].y * size)
		curveVertex(nodes[1].x * size, nodes[1].y * size)
		curveVertex(nodes[2].x * size, nodes[2].y * size)
	}
	endShape()
	pop()
}

const outline = (nodes, posX, posY, size, angle) => {
	push()
	posX *= CELL_SIZE
	posY *= CELL_SIZE
	size *= CELL_SIZE
	translate(posX, posY)
	rotate(angle)
	noFill()
	beginShape()
	nodes.forEach(({ x, y }) => curveVertex(x * size, y * size))
	endShape()
	pop()
}

const layer = ({ x, y, angle, flipX }, callback) => {
	push()
	translate(x, y)
	translate(CELL_SIZE / 2, CELL_SIZE / 2)
	rotate(angle)
	if (flipX) scale(-1, 1)
	translate(-CELL_SIZE / 2, -CELL_SIZE / 2)
	callback()
	pop()
}

const setPalette = (palette) => {
	;[FG_COLOR, BG_COLOR, STROKE_COLOR] = palette

	DECORATION_COLOR = FG_COLOR
	DECORATION_DOT_COLOR = BG_COLOR

	TRUCHET_COLOR = FG_COLOR
	TRUCHET_FEATHER_COLOR = BG_COLOR
	TRUCHET_FEATHER_DOT_COLOR = FG_COLOR
	TRUCHET_ZIGZAG_COLOR = BG_COLOR
	TRUCHET_ZIGZAG_DOTS_COLOR = BG_COLOR
	TRUCHET_CREST_SHORT_COLOR = BG_COLOR
	TRUCHET_CREST_LONG_COLOR = BG_COLOR
	TRUCHET_ARC_COLOR = BG_COLOR

	DINO_COLOR = FG_COLOR
	DINO_EYE_COLOR = BG_COLOR
	DINO_NOSE_COLOR = BG_COLOR
	DINO_TOOTH_COLOR = FG_COLOR
	DINO_SCAR_COLOR = BG_COLOR
	DINO_TATTOO_COLOR = STROKE_COLOR

	HUMAN_COLOR = FG_COLOR
	HUMAN_EYE_COLOR = BG_COLOR
	HUMAN_IRIS_COLOR = FG_COLOR
	HUMAN_NOSE_COLOR = BG_COLOR
	HUMAN_MOUTH_COLOR = BG_COLOR
	HUMAN_TATTOO_COLOR = STROKE_COLOR

	SKULL_COLOR = FG_COLOR
	SKULL_EYE_COLOR = STROKE_COLOR
	SKULL_TUBE_COLOR = FG_COLOR
	SKULL_CROSS_COLOR = FG_COLOR
	SKULL_CUBE_COLOR = FG_COLOR
}

const normalTruchet = (x, y, angle) => {
	layer({ x, y, angle }, () => {
